<?php
require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$id=(int)($_GET['id']??0);
$s=db()->prepare('SELECT l.*,p.nome paciente_nome,p.cpf paciente_cpf FROM laudos l JOIN pacientes p ON p.id=l.paciente_id WHERE l.id=? AND l.medico_id=?');$s->execute([$id,$m['id']]);$l=$s->fetch();if(!$l)exit('Laudo não encontrado.');
$body=trim((string)$l['conteudo_personalizado']);
$vars=['{{PACIENTE}}'=>$l['paciente_nome'],'{{CPF}}'=>$l['paciente_cpf'],'{{CID}}'=>$l['cid_codigo'],'{{CID_DESCRICAO}}'=>$l['cid_descricao'],'{{MEDICO}}'=>$m['nome_completo'],'{{CRM}}'=>$m['crm'].'/'.$m['uf'],'{{ESPECIALIDADE}}'=>$m['especialidade'],'{{DATA}}'=>date('d/m/Y',strtotime($l['data_emissao'])),'{{CONCLUSAO}}'=>$l['conclusao'],'{{HISTORICO}}'=>$l['historico_clinico'],'{{AVALIACAO}}'=>$l['avaliacao'],'{{EXAMES}}'=>$l['exames'],'{{REPERCUSSAO}}'=>$l['repercussao']];
if($body!=='')$body=nl2br(e(strtr($body,$vars)));else{$body='<h3>Identificação</h3><p><b>Paciente:</b> '.e($l['paciente_nome']).'</p><h3>História clínica</h3><p>'.nl2br(e($l['historico_clinico'])).'</p><h3>Avaliação / exame físico</h3><p>'.nl2br(e($l['avaliacao'])).'</p>'.($l['exames']?'<h3>Exames</h3><p>'.nl2br(e($l['exames'])).'</p>':'').'<h3>Diagnóstico</h3><p><b>CID-10:</b> '.e($l['cid_codigo']).' — '.e($l['cid_descricao']).'</p>'.($l['repercussao']?'<h3>Repercussão funcional</h3><p>'.nl2br(e($l['repercussao'])).'</p>':'').'<h3>Conclusão</h3><p>'.nl2br(e($l['conclusao'])).'</p>';}
$base=medical_base();$proto=(($_SERVER['HTTPS']??'')&&($_SERVER['HTTPS']!=='off'))?'https':'http';$validation=$proto.'://'.$_SERVER['HTTP_HOST'].$base.'/validar.php?id='.rawurlencode($l['codigo_validacao']);
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($l['titulo'])?></title><style>body{font:14px Arial;max-width:850px;margin:20px auto;line-height:1.65;background:#f5f7fa}.doc{background:#fff;border:1px solid #ddd;padding:45px;min-height:950px}.head{text-align:center;border-bottom:2px solid #163b63;padding-bottom:18px}.sign{text-align:center;margin-top:75px}.meta{font-size:12px;color:#666}@media print{body{background:#fff;margin:0}.no-print{display:none}.doc{border:0}}</style></head><body><div class="no-print"><button onclick="window.print()">Imprimir / Salvar PDF</button></div><article class="doc"><header class="head"><?php if(!empty($m['logo_path'])):?><img src="<?=e($base.'/assinatura.php?medico='.$m['id'].'&tipo=logo')?>" style="max-width:220px;max-height:90px"><br><?php endif;?><strong><?=e($m['nome_completo'])?></strong><br>CRM <?=e($m['crm'].'/'.$m['uf'])?><?php if($m['especialidade']):?> · <?=e($m['especialidade'])?><?php endif;?></header><h1 style="text-align:center"><?=e($l['titulo']?:'LAUDO MÉDICO')?></h1><?=$body?><p><?=e(date('d/m/Y',strtotime($l['data_emissao'])))?></p><div class="sign"><?php if(!empty($m['assinatura_path'])):?><img src="<?=e($base.'/assinatura.php?medico='.$m['id'])?>" style="max-width:220px;max-height:90px"><br><?php endif;?><b><?=e($m['nome_completo'])?></b><br>CRM <?=e($m['crm'].'/'.$m['uf'])?></div><div style="text-align:center;margin-top:25px"><img src="<?=e($base.'/qr.php?id='.rawurlencode($l['codigo_validacao']))?>" style="width:150px;height:150px"><br><small>Validação de autenticidade</small></div><hr><div class="meta">Código: <?=e($l['codigo_validacao'])?><br><?=e($validation)?></div></article></body></html>